   C8 (Z_to_bv 64 (Z.shiftr fb 3 + 2147450880)); CB 24 tj2; C8 (Z_to_bv 64 ff)].

(* [comment removed for export] *)
Definition fbp_WC1 (spa ff : Z) : list (Z * Z) := [(spa, spa + 96); (ff, ff + 128); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16)]%Z.

