Definition fbp_C1_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (fb n spa ff fp : Z) (FB : fbv) (t1 t2 t3 t4 t5 t6 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (a1x a3x a5x : word) m' (t0a tj2 hjunk' sh16' : list byte),
    ms' = MS (mkR (Z_to_bv 64 AFBP_NEW_RET) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1 t2
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_newsize FB n)) a1x (Z_to_bv 64 (fb + 40)) a3x (Z_to_bv 64 u64max)
                  a5x (Z_to_bv 64 ff) (Z_to_bv 64 n)
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
                  (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (fb + 16))
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom bsegs)
    /\ munch (fbp_WC1 spa ff) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' spa [CB 16 t0a] /\ rw_cells bsegs m' (spa + 16) (fbp_tmp3 (fb_newsize FB n) fb ff n tj2)
    /\ rw_cells bsegs m' ff [CB 120 hjunk'; C8 (Z_to_bv 64 fp)]
    /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 16 sh16'].
