Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

(* [comment removed for export] *)
Lemma fbp_C1 : forall (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (t1' t2' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo spa ff fp : Z) (FB : fbv) (mx : mem) (tj0 tj1 hjunk sh16 : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa (fbp_tmp2 tj0 tj1 fb ff) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  fresh_frame H LF 1 ff fp ->
  mem_inv bsegs mx ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= n -> fb_size FB + n < 2^27 -> fb_cap FB - fb_size FB < n -> aplace fb SZ_FB ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (fbp_C1_post sp gp tp F fc fb n spa ff fp FB t1' t2' t3' t4' t5' t6' mx)
    (fbp_TB_state sp gp tp F fc fb n spa ff FB t1' t2' t3' t4' t5' t6' mx).
