(* [comment removed for export] *)
Definition fbp_C_state (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (pcv rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word)
    (fb n spa ff a0v s10v : Z) (FB : fbv) (m : mem) : machine_state :=
  MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2
          sp (Z_to_bv 64 spa)
          (Z_to_bv 64 a0v) a1 a2 a3 a4 a5 a6 a7
          (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
          (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 s10v)
          (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
     F pcv fc None m (seg_rom bsegs).
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

(* [comment removed for export] *)
Lemma fbp_C2e : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp pn nsz : Z) (FB : fbv)
    (Q : mem -> Prop) (m0 mx : mem) (pfx gap : list cell) (tj2 hjunk sh16 : list byte),
  (pcv = Z_to_bv 64 AFBP_NEW_RET \/ pcv = ret_pc (Z_to_bv 64 AFBP_NEW_RET)) ->
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa pfx -> Z.of_nat (cells_size pfx) = 16 -> rw_cells bsegs mx (spa + 16) (fbp_tmp3 nsz fb ff n tj2) ->
  rw_cells bsegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 (b8 1)] ->
  rw_cells bsegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv bsegs mx -> as_RFS H LF m0 ->
  (forall m', munch (fbp_WA fb ff fp) mx m' -> wmono bsegs mx m' -> Q m') ->
  fb_begin FB = 0 -> 0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= n -> fb_size FB + n < 2^27 -> 0 < pn -> fb_size FB + n <= nsz -> pn + nsz <= aceil ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (fbp_endq_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF (fbp_WA fb ff fp) lo shi fb (pn + fb_size FB) n
               (mkFB pn pn (pn + fb_size FB) (pn + fb_size FB + n) (pn + nsz)) Q mx)
