Lemma fbp_C3 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp pn nsz a0v : Z) (FB : fbv)
    (Q : mem -> Prop) (m0 mx : mem) (gap : list cell) (t0b tj2 hjunk sh16 : list byte),
  (pcv = Z_to_bv 64 AFBP_DEL_RET \/ pcv = ret_pc (Z_to_bv 64 AFBP_DEL_RET)) ->
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa [CB 16 t0b] -> rw_cells bsegs mx (spa + 16) (fbp_tmp3 nsz fb ff n tj2) ->
  rw_cells bsegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
