(* [comment removed for export] *)
Definition fbp_WC2 (spa pn len : Z) : list (Z * Z) := [(spa, spa + 24); (pn, pn + len); (spa - AINTRIN_STACK, spa)]%Z.

Definition fbp_C2d_post (sp gp tp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (fb n lo shi spa ff fp pn nsz : Z) (FB : fbv) (gap : list cell) (ds t0a tj2 hjunk sh16 pre junk : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (rest : list byte),
    ms' = MS (mkR (Z_to_bv 64 AFBP_DEL_RET) (Z_to_bv 64 spa) gp tp t0 t1 t2
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 (fb_cap FB)) a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
                  (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 pn)
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
             F (Z_to_bv 64 AOPDEL2) fc None m' (seg_rom bsegs)
    /\ munch (fbp_WC2 spa pn (fb_size FB)) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' spa [CB 16 t0a] /\ rw_cells bsegs m' (spa + 16) (fbp_tmp3 nsz fb ff n tj2)
    /\ rw_cells bsegs m' (spa + 96) gap
    /\ rw_cells bsegs m' (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] /\ rw_cells bsegs m' fp [C1 (b8 1)]
    /\ rw_cells bsegs m' fb (FlatBufCells FB) /\ accessible m' fb SZ_FB
    /\ rw_cells bsegs m' (fb_begin FB) (fb_block_cells FB pre ds junk) /\ addressable m' (fb_begin FB) (fb_cap FB)
    /\ rw_cells bsegs m' pn [CB (length ds) ds; CB (Z.to_nat (nsz - fb_size FB)) rest] /\ addressable m' pn nsz
    /\ as_RFS H ((1, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.

Lemma fbp_C2d : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp pn nsz : Z) (FB : fbv)
    (m0 mx : mem) (gap : list cell) (t0a tj2 hjunk sh16 pre ds junk junkN : list byte),
  (pcv = Z_to_bv 64 AFBP_NEW_RET \/ pcv = ret_pc (Z_to_bv 64 AFBP_NEW_RET)) ->
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa [CB 16 t0a] -> rw_cells bsegs mx (spa + 16) (fbp_tmp3 nsz fb ff n tj2) ->
  rw_cells bsegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 (b8 1)] ->
  rw_cells bsegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv bsegs mx -> as_RFS H LF m0 ->
  (* [comment removed for export] *)
  rw_cells bsegs mx (fb_begin FB) (fb_block_cells FB pre ds junk) -> zlength ds = fb_size FB ->
  addressable mx (fb_begin FB) (fb_cap FB) -> shvis mx (fb_begin FB) (fb_end FB) -> aapp (fb_begin FB) (fb_cap FB) -> fsobj H LF (fb_begin FB) (fb_cap FB) ->
  (* [comment removed for export] *)
  rw_cells bsegs mx pn [CB (Z.to_nat nsz) junkN] -> addressable mx pn nsz -> shvis mx pn (pn + nsz) -> aapp pn nsz -> fsobj H LF pn nsz ->
  (fb_end FB <= pn \/ pn + nsz <= fb_begin FB) -> (fb + SZ_FB <= pn \/ pn + nsz <= fb) ->
